// Pagina del gestionale (servita da api/gate.js solo a chi ha fatto l'accesso)
module.exports = "<!DOCTYPE html>\n<html lang=\"it\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Gestionale — Studio Colarusso</title>\n<link rel=\"icon\" href=\"../favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital@0;1&family=Jost:wght@300;400;500&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--paper:#F9F8F6;--ink:#111;--red:#D32F2F;--grey:#77746F;--line:#E6E3DD;--soft:#F1EFEB;--white:#fff;--ok:#2E7D4F;--warn:#B7791F;\n  --display:'Playfair Display',Georgia,serif;--sans:'Jost','Helvetica Neue',Arial,sans-serif;--ease:cubic-bezier(.16,1,.3,1)}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{-webkit-tap-highlight-color:transparent}\nbody{background:var(--paper);color:var(--ink);font-family:var(--sans);font-weight:300;font-size:15px;line-height:1.5;-webkit-font-smoothing:antialiased}\nbutton{font:inherit;color:inherit;background:none;border:0;cursor:pointer}\na{color:inherit}\ninput,textarea,select{font:inherit;font-weight:400;color:var(--ink);background:var(--white);border:1px solid var(--line);padding:11px 13px;width:100%;border-radius:2px;outline:none;transition:border-color .2s}\ninput:focus,textarea:focus,select:focus{border-color:var(--ink)}\ntextarea{resize:vertical;min-height:90px;line-height:1.55}\nlabel.f{display:block;margin-bottom:18px}\nlabel.f > span{display:block;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--grey);margin-bottom:7px}\n.help{display:block;color:var(--grey);font-size:12.5px;margin-top:6px}\nh1,h2,h3{font-family:var(--display);font-weight:400;line-height:1.1}\n.hidden{display:none !important}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 20px;background:var(--ink);color:var(--paper);font-size:11px;letter-spacing:.18em;text-transform:uppercase;border-radius:2px;transition:background .2s,transform .1s;white-space:nowrap}\n.btn:hover{background:var(--red)}\n.btn:active{transform:scale(.97)}\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\n.btn.ghost:hover{border-color:var(--ink)}\n.btn.danger{background:transparent;color:var(--red);border:1px solid rgba(211,47,47,.35)}\n.btn.danger:hover{background:var(--red);color:#fff}\n.btn.sm{padding:8px 13px;font-size:10px}\n.btn:disabled{opacity:.4;pointer-events:none}\n.switch{display:flex;align-items:center;gap:12px;cursor:pointer;font-size:14px;margin-bottom:14px;user-select:none}\n.switch input{appearance:none;-webkit-appearance:none;width:38px;height:22px;border-radius:22px;background:var(--line);position:relative;padding:0;border:0;flex:none;cursor:pointer;transition:background .25s}\n.switch input::after{content:\"\";position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.2);transition:transform .25s var(--ease)}\n.switch input:checked{background:var(--ink)}\n.switch input:checked::after{transform:translateX(16px)}\n\n/* ACCESSO */\n.login{min-height:100vh;display:grid;grid-template-columns:1.1fr 1fr}\n.login-art{background:var(--ink);position:relative;overflow:hidden;display:flex;align-items:flex-end;padding:48px}\n.login-art img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.55;filter:grayscale(.2)}\n.login-art p{position:relative;color:var(--paper);font-family:var(--display);font-style:italic;font-size:1.6rem;max-width:420px;line-height:1.3}\n.login-form{display:grid;place-items:center;padding:32px}\n.login-box{width:100%;max-width:360px}\n.login-box .logo{width:190px;margin-bottom:34px}\n.login-box h1{font-size:2.2rem;margin-bottom:8px}\n.login-box > p{color:var(--grey);margin-bottom:30px}\n.err{color:var(--red);font-size:14px;margin-top:14px;min-height:1.3em}\n@media(max-width:800px){.login{grid-template-columns:1fr}.login-art{display:none}}\n\n/* STRUTTURA */\n.app{display:grid;grid-template-columns:250px 1fr;min-height:100vh}\n.side{position:sticky;top:0;height:100vh;background:var(--white);border-right:1px solid var(--line);display:flex;flex-direction:column;padding:26px 16px}\n.side .logo{width:150px;margin:0 10px 36px}\n.nav{display:flex;flex-direction:column;gap:2px}\n.nav button{display:flex;align-items:center;gap:13px;padding:11px 12px;border-radius:3px;font-size:14px;color:#555;text-align:left;transition:background .2s,color .2s}\n.nav button svg{width:18px;height:18px;flex:none;stroke:currentColor;fill:none;stroke-width:1.5}\n.nav button:hover{background:var(--soft);color:var(--ink)}\n.nav button.on{background:var(--ink);color:var(--paper)}\n.nav .count{margin-left:auto;background:var(--red);color:#fff;font-size:11px;font-weight:500;min-width:20px;height:20px;border-radius:10px;display:grid;place-items:center;padding:0 6px}\n.nav .count:empty{display:none}\n.side-foot{margin-top:auto;display:flex;flex-direction:column;gap:2px;border-top:1px solid var(--line);padding-top:14px}\n.side-foot a,.side-foot button{display:flex;align-items:center;gap:12px;padding:10px 12px;font-size:13px;color:var(--grey);text-decoration:none;text-align:left}\n.side-foot a:hover,.side-foot button:hover{color:var(--red)}\nmain{padding:40px clamp(18px,4vw,56px) 140px;max-width:1280px;width:100%}\n.head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:30px;flex-wrap:wrap}\n.head h2{font-size:clamp(2rem,3.4vw,2.8rem)}\n.head p{color:var(--grey);margin-top:8px;max-width:580px}\n.head .tools{display:flex;gap:10px;flex-wrap:wrap}\n\n/* PANORAMICA */\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:34px}\n.stat{background:var(--white);border:1px solid var(--line);padding:22px;border-radius:3px;cursor:pointer;transition:border-color .2s,transform .2s}\n.stat:hover{border-color:var(--ink);transform:translateY(-2px)}\n.stat b{display:block;font-family:var(--display);font-weight:400;font-size:2.6rem;line-height:1}\n.stat span{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--grey)}\n.stat.alert b{color:var(--red)}\n.two{display:grid;grid-template-columns:1.3fr 1fr;gap:20px}\n.box{background:var(--white);border:1px solid var(--line);border-radius:3px;padding:24px}\n.box h3{font-family:var(--sans);font-weight:400;font-size:11px;letter-spacing:.22em;text-transform:uppercase;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center}\n.box h3 button{font-size:11px;letter-spacing:.1em;text-transform:none;color:var(--grey)}\n.box h3 button:hover{color:var(--red)}\n.mini{display:flex;gap:14px;padding:12px 0;border-top:1px solid var(--line);cursor:pointer}\n.mini:first-of-type{border-top:0}\n.mini:hover b{color:var(--red)}\n.mini .dot{margin-top:8px}\n.mini b{font-weight:500;display:block}\n.mini small{color:var(--grey);display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:420px}\n.quick{display:grid;gap:10px}\n.quick .btn{justify-content:flex-start}\n.empty{color:var(--grey);font-size:14px;padding:10px 0}\n\n/* MESSAGGI */\n.chips{display:flex;gap:6px;flex-wrap:wrap}\n.chip{padding:8px 14px;border:1px solid var(--line);border-radius:20px;font-size:13px;background:var(--white);transition:all .2s}\n.chip.on{background:var(--ink);color:var(--paper);border-color:var(--ink)}\n.chip i{font-style:normal;opacity:.6;margin-left:4px}\n.inbox{display:grid;grid-template-columns:minmax(280px,380px) 1fr;background:var(--white);border:1px solid var(--line);border-radius:3px;min-height:560px;overflow:hidden}\n.list{border-right:1px solid var(--line);overflow-y:auto;max-height:72vh}\n.list .search{position:sticky;top:0;background:var(--white);padding:12px;border-bottom:1px solid var(--line);z-index:1}\n.item{display:flex;gap:12px;padding:16px 18px;border-bottom:1px solid var(--line);cursor:pointer;transition:background .15s}\n.item:hover{background:var(--paper)}\n.item.on{background:var(--soft)}\n.item .body{min-width:0;flex:1}\n.item .top{display:flex;justify-content:space-between;gap:8px}\n.item b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.item time{font-size:12px;color:var(--grey);white-space:nowrap}\n.item .mot{font-size:12px;color:var(--grey);letter-spacing:.04em}\n.item p{font-size:13.5px;color:#555;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.item.nuovo b{color:var(--ink)}\n.dot{width:8px;height:8px;border-radius:50%;flex:none;margin-top:7px;background:var(--line)}\n.dot.nuovo{background:var(--red)}.dot.in-corso{background:var(--warn)}.dot.risolto{background:var(--ok)}\n.detail{padding:30px 34px;overflow-y:auto;max-height:72vh}\n.detail .placeholder{height:100%;display:grid;place-items:center;color:var(--grey);text-align:center;min-height:400px}\n.d-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;padding-bottom:20px;border-bottom:1px solid var(--line);margin-bottom:22px;flex-wrap:wrap}\n.d-head h3{font-size:1.9rem;margin-bottom:6px}\n.d-head a{color:var(--grey);text-decoration:none;font-size:14px}\n.d-head a:hover{color:var(--red)}\n.d-head time{font-size:13px;color:var(--grey)}\n.tag{display:inline-block;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;border:1px solid var(--line);padding:4px 9px;border-radius:2px;margin:0 6px 6px 0}\n.d-opera{display:flex;gap:14px;align-items:center;background:var(--paper);border:1px solid var(--line);padding:10px;margin:6px 0 20px;border-radius:3px}\n.d-opera img{width:56px;height:56px;object-fit:contain}\n.d-opera small{display:block;color:var(--grey);font-size:11px;letter-spacing:.14em;text-transform:uppercase}\n.d-msg{font-size:16px;line-height:1.75;white-space:pre-wrap;margin-bottom:28px}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:3px;overflow:hidden;margin-bottom:24px}\n.seg button{padding:9px 16px;font-size:13px;display:flex;align-items:center;gap:8px;border-left:1px solid var(--line)}\n.seg button:first-child{border-left:0}\n.seg button .dot{margin:0}\n.seg button.on{background:var(--ink);color:var(--paper)}\n.d-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}\n.setup{background:var(--white);border:1px solid var(--line);padding:30px;border-radius:3px;max-width:720px}\n.setup ol{margin:14px 0 0 20px;display:grid;gap:8px}\n\n/* OPERE */\n.bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:22px}\n.bar input[type=search]{max-width:280px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:18px}\n.card{background:var(--white);border:1px solid var(--line);border-radius:3px;cursor:pointer;transition:border-color .2s,transform .2s,box-shadow .2s;position:relative;display:flex;flex-direction:column}\n.card:hover{border-color:var(--ink);transform:translateY(-3px);box-shadow:0 14px 30px -18px rgba(0,0,0,.35)}\n.card.off{opacity:.45}\n.card .ph{aspect-ratio:1;display:grid;place-items:center;padding:14px;background:var(--paper)}\n.card .ph img{max-width:100%;max-height:100%;object-fit:contain}\n.card .meta{padding:11px 13px;border-top:1px solid var(--line)}\n.card b{display:block;font-family:var(--display);font-weight:400;font-style:italic;font-size:1.05rem;line-height:1.25}\n.card small{color:var(--grey);font-size:12px}\n.badges{position:absolute;top:8px;left:8px;display:flex;gap:4px;flex-wrap:wrap}\n.badge{font-size:9px;letter-spacing:.12em;text-transform:uppercase;background:var(--ink);color:#fff;padding:3px 7px;border-radius:2px}\n.badge.red{background:var(--red)}.badge.ok{background:var(--ok)}.badge.grey{background:var(--grey)}\n\n.panel{background:var(--white);border:1px solid var(--line);border-radius:3px;padding:30px;max-width:780px}\n.panel h3{font-family:var(--sans);font-weight:400;font-size:11px;letter-spacing:.22em;text-transform:uppercase;margin:4px 0 18px;padding-bottom:10px;border-bottom:1px solid var(--line)}\n.panel h3:not(:first-child){margin-top:36px}\n\n/* EDITOR OPERA */\n.drawer-bg{position:fixed;inset:0;background:rgba(17,17,17,.35);z-index:40;backdrop-filter:blur(2px)}\n.drawer{position:fixed;top:0;right:0;bottom:0;width:min(680px,100%);background:var(--paper);z-index:41;overflow-y:auto;padding:30px 34px 60px;box-shadow:-20px 0 60px rgba(0,0,0,.15);animation:slide .45s var(--ease)}\n@keyframes slide{from{transform:translateX(40px);opacity:0}}\n.drawer h2{font-size:2rem;margin-bottom:24px;padding-right:90px}\n.drawer .x{position:absolute;top:30px;right:30px;font-size:11px;letter-spacing:.2em;text-transform:uppercase}\n.drawer .x:hover{color:var(--red)}\n.photo{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:12px}\n.photo figure{border:1px solid var(--line);aspect-ratio:1;display:grid;place-items:center;padding:12px;position:relative;background:var(--paper);border-radius:3px}\n.photo figure.chk{background-color:#fff;background-image:linear-gradient(45deg,#eee 25%,transparent 25%),linear-gradient(-45deg,#eee 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#eee 75%),linear-gradient(-45deg,transparent 75%,#eee 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0}\n.photo img{max-width:100%;max-height:100%;object-fit:contain}\n.photo figcaption{position:absolute;bottom:7px;left:8px;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--grey);background:rgba(255,255,255,.9);padding:2px 7px}\n.upload{display:block;border:1px dashed #bdb8b0;padding:22px;text-align:center;cursor:pointer;margin-bottom:12px;border-radius:3px;background:var(--white);transition:border-color .2s,background .2s}\n.upload:hover,.upload.drag{border-color:var(--red);background:#fff}\n.upload input{display:none}\n.upload small{color:var(--grey)}\n.opts{display:flex;gap:22px;flex-wrap:wrap;margin:8px 0 22px}\n.row2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.row3{display:grid;grid-template-columns:1fr auto 1fr auto;gap:10px;align-items:center}\n.row3 em{font-style:normal;color:var(--grey)}\n.toggles{background:var(--white);border:1px solid var(--line);padding:18px 18px 6px;border-radius:3px;margin:6px 0 10px}\n.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px;padding-top:22px;border-top:1px solid var(--line)}\n.actions .sp{flex:1}\n\n/* PUBBLICAZIONE, AVVISI */\n.pub{position:fixed;left:250px;right:0;bottom:0;z-index:30;background:var(--ink);color:var(--paper);display:flex;align-items:center;gap:16px;padding:14px clamp(18px,4vw,56px);transform:translateY(110%);transition:transform .45s var(--ease)}\n.pub.show{transform:none}\n.pub p{flex:1;font-size:14px}\n.pub .btn{background:var(--red)}\n.pub .btn:hover{background:#fff;color:var(--ink)}\n.pub .btn.ghost{background:transparent;border-color:#444;color:#bbb}\n.toast{position:fixed;left:50%;bottom:92px;transform:translateX(-50%);background:var(--white);border:1px solid var(--ink);padding:12px 18px;z-index:80;font-size:14px;box-shadow:0 10px 30px rgba(0,0,0,.15);max-width:90vw;border-radius:3px;animation:slide .35s var(--ease)}\n.toast.ok{border-color:var(--ok);color:var(--ok)}\n.toast.bad{border-color:var(--red);color:var(--red)}\n.busy{position:fixed;inset:0;background:rgba(249,248,246,.85);z-index:90;display:grid;place-items:center;font-size:12px;letter-spacing:.2em;text-transform:uppercase}\n\n/* TELEFONO */\n.mtop{display:none}\n@media(max-width:900px){\n  .app{grid-template-columns:1fr}\n  .side{position:fixed;inset:auto 0 0 0;height:auto;flex-direction:row;padding:6px 6px calc(6px + env(safe-area-inset-bottom));border-right:0;border-top:1px solid var(--line);z-index:35}\n  .side .logo,.side-foot{display:none}\n  .nav{flex-direction:row;width:100%;justify-content:space-around}\n  .nav button{flex-direction:column;gap:3px;font-size:10px;padding:7px 4px;position:relative;flex:1;align-items:center}\n  .nav button .lbl-long{display:none}\n  .nav button .lbl-short{display:inline}\n  .nav .count{position:absolute;top:2px;right:18%;margin:0;min-width:17px;height:17px;font-size:10px}\n  .mtop{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid var(--line);background:var(--white);position:sticky;top:0;z-index:20}\n  .mtop img{height:24px}\n  .mtop a,.mtop button{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--grey);text-decoration:none}\n  main{padding:24px 16px 150px}\n  .stats{grid-template-columns:1fr 1fr}\n  .two{grid-template-columns:1fr}\n  .inbox{grid-template-columns:1fr}\n  .list{max-height:none;border-right:0}\n  .detail{max-height:none}\n  .inbox.reading .list{display:none}\n  .inbox:not(.reading) .detail{display:none}\n  .back{display:inline-flex !important}\n  .pub{left:0;bottom:62px}\n  .row2,.photo{grid-template-columns:1fr 1fr}\n  .drawer{padding:24px 18px 80px}\n}\n.back{display:none;margin-bottom:16px}\n.lbl-short{display:none}\n</style>\n</head>\n<body>\n\n<!-- ============ ACCESSO ============ -->\n<section class=\"login\" id=\"login\">\n  <div class=\"login-art\"><img class=\"bg\" src=\"../opera-41.webp\" alt=\"\" onerror=\"this.src='../img/opere/opera-41.webp'\"><p>“Lo strappo non è un atto distruttivo, ma un processo rivelatore.”</p></div>\n  <div class=\"login-form\">\n    <form class=\"login-box\" id=\"loginForm\">\n      <img class=\"logo\" src=\"../logo.png\" alt=\"Studio Colarusso\">\n      <h1>Area riservata</h1>\n      <p>Inserisci la password per gestire il sito.</p>\n      <div id=\"stepPw\">\n        <label class=\"f\"><span>Password</span><input name=\"password\" type=\"password\" autocomplete=\"current-password\" autofocus></label>\n      </div>\n      <div id=\"stepCode\" class=\"hidden\">\n        <p style=\"margin-bottom:16px\">Ti abbiamo inviato un <b>codice di 6 cifre</b> alla email dello studio. Inseriscilo qui (vale 10 minuti).</p>\n        <label class=\"f\"><span>Codice</span><input name=\"code\" inputmode=\"numeric\" autocomplete=\"one-time-code\" maxlength=\"7\" placeholder=\"000000\" style=\"font-size:22px;letter-spacing:.4em;text-align:center\"></label>\n        <label class=\"switch\"><input type=\"checkbox\" name=\"remember\" checked> Ricorda questo dispositivo per 30 giorni</label>\n      </div>\n      <button class=\"btn\" type=\"submit\" style=\"width:100%\">Entra</button>\n      <p class=\"err\" id=\"loginErr\"></p>\n      <button type=\"button\" class=\"hidden\" id=\"restart\" style=\"font-size:13px;color:var(--grey);margin-top:6px\">← Torna alla password</button>\n    </form>\n  </div>\n</section>\n\n<!-- ============ GESTIONALE ============ -->\n<div class=\"app hidden\" id=\"app\">\n  <aside class=\"side\">\n    <img class=\"logo\" src=\"../logo.png\" alt=\"Studio Colarusso\">\n    <nav class=\"nav\" id=\"nav\">\n      <button data-tab=\"home\" class=\"on\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 11l8-7 8 7v9H4z\"/><path d=\"M9 20v-6h6v6\"/></svg><span>Panoramica</span></button>\n      <button data-tab=\"messaggi\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"1\"/><path d=\"M3 7l9 6 9-6\"/></svg><span>Messaggi</span><em class=\"count\" id=\"cntMsg\"></em></button>\n      <button data-tab=\"opere\"><svg viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"3\" width=\"16\" height=\"18\"/><path d=\"M4 16l5-5 4 4 3-3 4 4\"/></svg><span>Opere</span></button>\n      <button data-tab=\"contatti\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c1-4 4-6 8-6s7 2 8 6\"/></svg><span class=\"lbl-long\">Contatti e social</span><span class=\"lbl-short\">Contatti</span></button>\n      <button data-tab=\"testi\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 5h14M5 10h14M5 15h9M5 20h6\"/></svg><span>Testi</span></button>\n    </nav>\n    <div class=\"side-foot\">\n      <a href=\"../\" target=\"_blank\" rel=\"noopener\">↗ Vedi il sito</a>\n      <button id=\"logout\">⎋ Esci</button>\n    </div>\n  </aside>\n\n  <div>\n    <div class=\"mtop\"><img src=\"../logo.png\" alt=\"\"><span><a href=\"../\" target=\"_blank\" rel=\"noopener\">Sito ↗</a> &nbsp; <button id=\"logoutM\">Esci</button></span></div>\n    <main>\n      <!-- PANORAMICA -->\n      <section data-view=\"home\">\n        <div class=\"head\"><div><h2 id=\"hello\">Buongiorno</h2><p>Ecco com'è il tuo sito oggi.</p></div></div>\n        <div class=\"stats\">\n          <div class=\"stat\" data-go=\"messaggi\" id=\"stNew\"><b>–</b><span>Messaggi da gestire</span></div>\n          <div class=\"stat\" data-go=\"opere\" id=\"stWorks\"><b>–</b><span>Opere pubblicate</span></div>\n          <div class=\"stat\" data-go=\"opere\" id=\"stSel\"><b>–</b><span>In evidenza</span></div>\n          <div class=\"stat\" data-go=\"opere\" id=\"stHidden\"><b>–</b><span>Nascoste</span></div>\n        </div>\n        <div class=\"two\">\n          <div class=\"box\"><h3>Ultimi messaggi <button data-go=\"messaggi\">Vedi tutti →</button></h3><div id=\"lastMsgs\"></div></div>\n          <div class=\"box\"><h3>Azioni rapide</h3>\n            <div class=\"quick\">\n              <button class=\"btn\" data-quick=\"add\">+ Aggiungi un'opera</button>\n              <button class=\"btn ghost\" data-quick=\"multi\">Carica più foto insieme</button>\n              <button class=\"btn ghost\" data-go=\"testi\">Modifica biografia e testi</button>\n              <a class=\"btn ghost\" href=\"../\" target=\"_blank\" rel=\"noopener\">Apri il sito ↗</a>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- MESSAGGI -->\n      <section data-view=\"messaggi\" class=\"hidden\">\n        <div class=\"head\">\n          <div><h2>Messaggi</h2><p>Le richieste arrivate dal modulo contatti del sito.</p></div>\n          <div class=\"chips\" id=\"msgFilter\">\n            <button class=\"chip on\" data-f=\"aperti\">Da gestire <i id=\"fOpen\"></i></button>\n            <button class=\"chip\" data-f=\"risolto\">Risolti <i id=\"fDone\"></i></button>\n            <button class=\"chip\" data-f=\"tutti\">Tutti <i id=\"fAll\"></i></button>\n          </div>\n        </div>\n        <div class=\"setup hidden\" id=\"msgSetup\">\n          <h3 style=\"margin-bottom:8px\">Attiva l'archivio dei messaggi</h3>\n          <p style=\"color:var(--grey)\">Per vedere qui i messaggi serve collegare un piccolo archivio gratuito al progetto (una volta sola):</p>\n          <ol>\n            <li>Su Vercel apri il progetto <b>studio-Colarusso</b> → scheda <b>Storage</b>.</li>\n            <li><b>Create Database</b> (o <b>Connect Database</b>) → scegli <b>Upstash</b> → <b>Redis</b> → piano gratuito.</li>\n            <li>Collegalo al progetto <b>studio-Colarusso</b> (tutti gli ambienti) → <b>Connect</b>.</li>\n            <li>Vai in <b>Deployments</b> → sull'ultimo \"…\" → <b>Redeploy</b>. Fatto: i nuovi messaggi compariranno qui.</li>\n          </ol>\n          <p class=\"help\" style=\"margin-top:14px\">Nel frattempo i messaggi continuano ad arrivare alla tua email.</p>\n        </div>\n        <div class=\"inbox\" id=\"inbox\">\n          <div class=\"list\"><div class=\"search\"><input type=\"search\" id=\"msgSearch\" placeholder=\"Cerca per nome, email o testo…\"></div><div id=\"msgList\"></div></div>\n          <div class=\"detail\" id=\"msgDetail\"><div class=\"placeholder\">Seleziona un messaggio<br>per leggerlo.</div></div>\n        </div>\n      </section>\n\n      <!-- OPERE -->\n      <section data-view=\"opere\" class=\"hidden\">\n        <div class=\"head\">\n          <div><h2>Opere</h2><p>Clicca un'opera per modificarla. Le modifiche vanno online quando premi <b>Pubblica sul sito</b>.</p></div>\n          <div class=\"tools\">\n            <label class=\"btn ghost\" style=\"cursor:pointer\">Carica più foto<input type=\"file\" id=\"multiFile\" accept=\"image/*\" multiple hidden></label>\n            <button class=\"btn\" id=\"addBtn\">+ Aggiungi opera</button>\n          </div>\n        </div>\n        <div class=\"bar\">\n          <input type=\"search\" id=\"workSearch\" placeholder=\"Cerca per titolo o anno…\">\n          <div class=\"chips\" id=\"workFilter\">\n            <button class=\"chip on\" data-f=\"tutte\">Tutte</button>\n            <button class=\"chip\" data-f=\"evidenza\">★ In evidenza</button>\n            <button class=\"chip\" data-f=\"nascoste\">Nascoste</button>\n          </div>\n        </div>\n        <div class=\"grid\" id=\"grid\"></div>\n      </section>\n\n      <!-- CONTATTI -->\n      <section data-view=\"contatti\" class=\"hidden\">\n        <div class=\"head\"><div><h2>Contatti e social</h2><p>Se lasci vuoto un social, la sua icona sparisce dal sito.</p></div></div>\n        <div class=\"panel\">\n          <label class=\"f\"><span>Email mostrata sul sito</span><input data-bind=\"contatti.email\" type=\"email\"></label>\n          <label class=\"f\"><span>Link Instagram</span><input data-bind=\"contatti.instagram\" placeholder=\"https://www.instagram.com/...\"></label>\n          <label class=\"f\"><span>Link TikTok</span><input data-bind=\"contatti.tiktok\" placeholder=\"https://www.tiktok.com/@...\"></label>\n        </div>\n      </section>\n\n      <!-- TESTI -->\n      <section data-view=\"testi\" class=\"hidden\">\n        <div class=\"head\"><div><h2>Testi</h2><p>Nei riquadri con più paragrafi lascia una riga vuota tra un paragrafo e l'altro.</p></div></div>\n        <div class=\"panel\">\n          <h3>Apertura</h3>\n          <label class=\"f\"><span>Frase sotto il titolo</span><textarea data-bind=\"testi.heroSottotitolo\" rows=\"2\"></textarea></label>\n          <h3>Poetica</h3>\n          <label class=\"f\"><span>Introduzione</span><textarea data-bind=\"testi.poeticaIntro\" rows=\"3\"></textarea></label>\n          <label class=\"f\"><span>I · L'indagine psicologica</span><textarea data-bind=\"testi.poetica1\" data-type=\"paras\" rows=\"7\"></textarea></label>\n          <label class=\"f\"><span>Citazione</span><textarea data-bind=\"testi.citazione\" rows=\"2\"></textarea></label>\n          <label class=\"f\"><span>II · La memoria visiva</span><textarea data-bind=\"testi.poetica2\" data-type=\"paras\" rows=\"7\"></textarea></label>\n          <h3>Biografia</h3>\n          <label class=\"f\"><span>Testo (il primo paragrafo appare più grande)</span><textarea data-bind=\"testi.biografia\" data-type=\"paras\" rows=\"14\"></textarea></label>\n          <label class=\"f\"><span>Tappe</span><textarea data-bind=\"testi.tappe\" data-type=\"tappe\" rows=\"6\"></textarea><small class=\"help\">Una tappa per riga, nella forma: Anno | Descrizione</small></label>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <div class=\"pub\" id=\"pub\">\n    <p id=\"pubText\">Hai modifiche non ancora pubblicate.</p>\n    <button class=\"btn ghost\" id=\"discardBtn\">Annulla</button>\n    <button class=\"btn\" id=\"publishBtn\">Pubblica sul sito</button>\n  </div>\n</div>\n\n<!-- EDITOR OPERA -->\n<div class=\"drawer-bg hidden\" id=\"drawerBg\"></div>\n<aside class=\"drawer hidden\" id=\"drawer\" aria-label=\"Modifica opera\">\n  <button class=\"x\" id=\"drawerClose\">Chiudi ✕</button>\n  <h2 id=\"dTitle\">Opera</h2>\n\n  <div class=\"photo\">\n    <figure><img id=\"dImg\" alt=\"\"><figcaption>Come appare sul sito</figcaption></figure>\n    <figure class=\"chk\"><img id=\"dOrig\" alt=\"\"><figcaption>Foto caricata</figcaption></figure>\n  </div>\n  <label class=\"upload\" id=\"drop\">\n    <input type=\"file\" id=\"file\" accept=\"image/*\">\n    <b id=\"dropTxt\">Carica la foto dell'opera</b><br><small>Clicca o trascina qui un'immagine</small>\n  </label>\n  <div class=\"opts\">\n    <label class=\"switch\"><input type=\"checkbox\" id=\"optCut\" checked> Scontorna (togli la parete)</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"optTrim\" checked> Taglia fino alla cornice</label>\n  </div>\n\n  <label class=\"f\"><span>Titolo</span><input id=\"fTitolo\" placeholder=\"es. Senza titolo (Marilyn)\"></label>\n  <div class=\"row2\">\n    <label class=\"f\"><span>Anno</span><input id=\"fAnno\" inputmode=\"numeric\" placeholder=\"es. 2025\"></label>\n    <label class=\"f\"><span>Tecnica</span><input id=\"fTecnica\" list=\"tecniche\"></label>\n  </div>\n  <datalist id=\"tecniche\">\n    <option>Décollage su carta</option><option>Décollage su tela</option><option>Décollage su tavola</option>\n    <option>Décollage digitale</option><option>Tecnica mista su tela</option>\n  </datalist>\n  <label class=\"f\"><span>Misure (cm)</span>\n    <div class=\"row3\"><input id=\"fW\" inputmode=\"decimal\" placeholder=\"Base\"><em>×</em><input id=\"fH\" inputmode=\"decimal\" placeholder=\"Altezza\"><em>cm</em></div>\n    <small class=\"help\">Per le opere tonde scrivi il diametro in \"Base\" e lascia vuota l'altezza.</small>\n  </label>\n  <label class=\"f\"><span>Descrizione</span><textarea id=\"fDesc\" rows=\"3\" placeholder=\"Poche righe che accompagnano l'opera\"></textarea></label>\n  <label class=\"f\"><span>La genesi di quest'opera</span><textarea id=\"fGenesi\" rows=\"4\" placeholder=\"Quali manifesti, quando, quale emozione…\"></textarea><small class=\"help\">Se lo lasci vuoto, il pulsante \"La genesi\" non appare sul sito.</small></label>\n  <div class=\"toggles\">\n    <label class=\"switch\"><input type=\"checkbox\" id=\"fSel\"> ★ In evidenza nella galleria grande</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"fHero\"> Opera in apertura del sito</label>\n    <label class=\"switch\"><input type=\"checkbox\" id=\"fHide\"> Nascondi dal sito (resta salvata qui)</label>\n  </div>\n\n  <div class=\"actions\">\n    <button class=\"btn ghost sm\" id=\"upBtn\">↑ Prima</button>\n    <button class=\"btn ghost sm\" id=\"downBtn\">↓ Dopo</button>\n    <span class=\"sp\"></span>\n    <button class=\"btn danger sm\" id=\"delBtn\">Elimina</button>\n    <button class=\"btn\" id=\"saveBtn\">Salva</button>\n  </div>\n</aside>\n\n<div class=\"busy hidden\" id=\"busy\">Pubblicazione in corso…</div>\n\n<script>\n(() => {\n\"use strict\";\nconst $ = (s, c = document) => c.querySelector(s);\nconst $$ = (s, c = document) => [...c.querySelectorAll(s)];\nconst esc = s => String(s ?? \"\").replace(/[&<>\"]/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\nconst pad2 = n => String(n).padStart(2, \"0\");\n\nlet sito = null, original = \"\", files = new Map(), removed = new Set();\nlet editing = null, pending = null, lastFile = null;\nlet msgs = [], msgConfigured = true, msgFilter = \"aperti\", currentMsg = null;\nlet workFilter = \"tutte\";\n\n/* ---------------- Server ---------------- */\nasync function api(path, body, method) {\n  const opts = body === undefined && !method ? { credentials: \"same-origin\", cache: \"no-store\" }\n    : { method: method || \"POST\", credentials: \"same-origin\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(body || {}) };\n  const r = await fetch(\"/api/admin/\" + path, opts);\n  let j = {}; try { j = await r.json(); } catch (e) {}\n  if (r.status === 401 && path !== \"login\") showLogin(\"Sessione scaduta: accedi di nuovo.\");\n  if (!r.ok) { const err = new Error(j.error || (\"Errore \" + r.status)); err.status = r.status; throw err; }\n  return j;\n}\nconst blobB64 = blob => new Promise(res => { const fr = new FileReader(); fr.onload = () => res(fr.result.split(\",\")[1]); fr.readAsDataURL(blob); });\n\nasync function loadData() {\n  sito = await api(\"data\");\n  sito.contatti ||= {}; sito.testi ||= {}; sito.selezione ||= []; sito.opere ||= [];\n  original = JSON.stringify(sito); files.clear(); removed.clear();\n}\nasync function loadMessages() {\n  try {\n    const r = await api(\"messages\");\n    msgConfigured = r.configured; msgs = r.messages || [];\n  } catch (e) { msgs = []; }\n  renderMessages(); renderHome();\n}\n\n/* ---------------- Accesso ---------------- */\nconst lf = $(\"#loginForm\");\nfunction setStep(code) {\n  $(\"#stepPw\").classList.toggle(\"hidden\", code); $(\"#stepCode\").classList.toggle(\"hidden\", !code); $(\"#restart\").classList.toggle(\"hidden\", !code);\n  (code ? lf.code : lf.password).focus();\n}\nfunction showLogin(msg) {\n  $(\"#app\").classList.add(\"hidden\"); $(\"#login\").classList.remove(\"hidden\");\n  $(\"#loginErr\").textContent = msg || \"\"; lf.password.value = \"\"; lf.code.value = \"\"; setStep(false);\n}\n$(\"#restart\").onclick = () => { $(\"#loginErr\").textContent = \"\"; lf.code.value = \"\"; setStep(false); };\nasync function enter() {\n  await loadData();\n  $(\"#login\").classList.add(\"hidden\"); $(\"#app\").classList.remove(\"hidden\");\n  renderWorks(); bindFields(); refresh(); renderHome();\n  loadMessages();\n}\nlf.addEventListener(\"submit\", async e => {\n  e.preventDefault();\n  const codeStep = !$(\"#stepCode\").classList.contains(\"hidden\");\n  if (!codeStep && !lf.password.value) return;\n  if (codeStep && !lf.code.value.trim()) return;\n  $(\"#loginErr\").textContent = codeStep ? \"Verifica…\" : \"Accesso…\";\n  const btn = lf.querySelector(\"button[type=submit]\"); btn.disabled = true;\n  try {\n    const r = await api(\"login\", codeStep ? { code: lf.code.value, remember: lf.remember.checked } : { password: lf.password.value });\n    if (r.step === \"code\") { $(\"#loginErr\").textContent = \"\"; lf.password.value = \"\"; setStep(true); return; }\n    $(\"#loginErr\").textContent = \"\"; await enter();\n  } catch (err) {\n    $(\"#loginErr\").textContent = err.message;\n    if (/scadut/.test(err.message)) setStep(false);\n  } finally { btn.disabled = false; }\n});\napi(\"session\").then(r => { if (r.logged) enter().catch(e => showLogin(e.message)); }).catch(() => {});\nasync function logout(e) {\n  e.preventDefault();\n  if (dirty() && !confirm(\"Hai modifiche non pubblicate. Uscire comunque?\")) return;\n  try { await api(\"logout\", {}); } catch (err) {}\n  location.href = \"/\";\n}\n$(\"#logout\").onclick = logout; $(\"#logoutM\").onclick = logout;\n\n/* ---------------- Navigazione ---------------- */\nfunction go(tab) {\n  $$(\"#nav button\").forEach(x => x.classList.toggle(\"on\", x.dataset.tab === tab));\n  $$(\"[data-view]\").forEach(v => v.classList.toggle(\"hidden\", v.dataset.view !== tab));\n  scrollTo(0, 0);\n  if (tab === \"messaggi\") loadMessages();\n}\n$$(\"#nav button\").forEach(b => b.onclick = () => go(b.dataset.tab));\ndocument.addEventListener(\"click\", e => { const g = e.target.closest(\"[data-go]\"); if (g) go(g.dataset.go); });\n\n/* ---------------- Panoramica ---------------- */\nconst openMsgs = () => msgs.filter(m => m.stato !== \"risolto\");\nfunction renderHome() {\n  if (!sito) return;\n  const h = new Date().getHours();\n  $(\"#hello\").textContent = h < 13 ? \"Buongiorno\" : h < 18 ? \"Buon pomeriggio\" : \"Buonasera\";\n  const vis = sito.opere.filter(o => !o.nascosta);\n  $(\"#stNew b\").textContent = msgConfigured ? openMsgs().length : \"–\";\n  $(\"#stNew\").classList.toggle(\"alert\", openMsgs().length > 0);\n  $(\"#stWorks b\").textContent = vis.length;\n  $(\"#stSel b\").textContent = sito.selezione.filter(n => vis.some(o => o.n === n)).length;\n  $(\"#stHidden b\").textContent = sito.opere.length - vis.length;\n  $(\"#cntMsg\").textContent = openMsgs().filter(m => m.stato === \"nuovo\").length || \"\";\n  const last = msgs.slice(0, 4);\n  $(\"#lastMsgs\").innerHTML = !msgConfigured ? '<p class=\"empty\">Archivio messaggi non ancora attivo: apri la sezione Messaggi per attivarlo.</p>'\n    : last.length ? last.map(m => `<div class=\"mini\" data-open=\"${m.id}\"><span class=\"dot ${m.stato}\"></span><div><b>${esc(m.nome)}</b><small>${esc(m.motivo)} · ${esc(m.messaggio)}</small></div></div>`).join(\"\")\n    : '<p class=\"empty\">Nessun messaggio per ora.</p>';\n}\n$(\"#lastMsgs\").addEventListener(\"click\", e => { const m = e.target.closest(\"[data-open]\"); if (m) { go(\"messaggi\"); openMsg(m.dataset.open); } });\ndocument.addEventListener(\"click\", e => {\n  const q = e.target.closest(\"[data-quick]\"); if (!q) return;\n  if (q.dataset.quick === \"add\") { go(\"opere\"); openEditor(-1); }\n  if (q.dataset.quick === \"multi\") { go(\"opere\"); $(\"#multiFile\").click(); }\n});\n\n/* ---------------- Messaggi ---------------- */\nconst when = ts => {\n  const d = new Date(ts), diff = (Date.now() - ts) / 1000;\n  if (diff < 3600) return Math.max(1, Math.round(diff / 60)) + \" min fa\";\n  if (diff < 86400) return Math.round(diff / 3600) + \" ore fa\";\n  if (diff < 7 * 86400) return d.toLocaleDateString(\"it-IT\", { weekday: \"long\" });\n  return d.toLocaleDateString(\"it-IT\", { day: \"numeric\", month: \"short\", year: diff > 300 * 86400 ? \"numeric\" : undefined });\n};\nconst STATO = { \"nuovo\": \"Nuovo\", \"in-corso\": \"In corso\", \"risolto\": \"Risolto\" };\nfunction filteredMsgs() {\n  const q = $(\"#msgSearch\").value.trim().toLowerCase();\n  return msgs.filter(m => msgFilter === \"tutti\" ? true : msgFilter === \"risolto\" ? m.stato === \"risolto\" : m.stato !== \"risolto\")\n    .filter(m => !q || [m.nome, m.email, m.messaggio, m.motivo, m.opera].join(\" \").toLowerCase().includes(q));\n}\nfunction renderMessages() {\n  $(\"#msgSetup\").classList.toggle(\"hidden\", msgConfigured);\n  $(\"#inbox\").classList.toggle(\"hidden\", !msgConfigured);\n  $(\"#fOpen\").textContent = openMsgs().length; $(\"#fDone\").textContent = msgs.length - openMsgs().length; $(\"#fAll\").textContent = msgs.length;\n  const list = filteredMsgs();\n  $(\"#msgList\").innerHTML = list.length ? list.map(m => `\n    <div class=\"item ${m.stato} ${currentMsg === m.id ? \"on\" : \"\"}\" data-id=\"${m.id}\">\n      <span class=\"dot ${m.stato}\"></span>\n      <div class=\"body\">\n        <div class=\"top\"><b>${esc(m.nome)}</b><time>${when(m.ts)}</time></div>\n        <div class=\"mot\">${esc(m.motivo)}${m.opera ? \" · \" + esc(m.opera) : \"\"}</div>\n        <p>${esc(m.messaggio)}</p>\n      </div>\n    </div>`).join(\"\") : `<p class=\"empty\" style=\"padding:20px\">${msgFilter === \"risolto\" ? \"Nessun messaggio risolto.\" : \"Nessun messaggio da gestire. Tutto in ordine.\"}</p>`;\n  renderHome();\n}\n$(\"#msgList\").addEventListener(\"click\", e => { const it = e.target.closest(\".item\"); if (it) openMsg(it.dataset.id); });\n$(\"#msgSearch\").oninput = renderMessages;\n$$(\"#msgFilter .chip\").forEach(c => c.onclick = () => { msgFilter = c.dataset.f; $$(\"#msgFilter .chip\").forEach(x => x.classList.toggle(\"on\", x === c)); renderMessages(); });\n\nfunction operaOf(m) {\n  const n = (m.opera || \"\").match(/n\\. (\\d+)/);\n  return n ? sito.opere.find(o => o.n === +n[1]) : null;\n}\nfunction openMsg(id) {\n  const m = msgs.find(x => x.id === id); if (!m) return;\n  currentMsg = id;\n  const o = operaOf(m);\n  const subject = encodeURIComponent(\"Re: \" + (m.motivo || \"Il tuo messaggio\") + \" — Studio Colarusso\");\n  const body = encodeURIComponent(`Ciao ${m.nome.split(\" \")[0]},\\n\\n\\n\\n—\\nGiuseppe Colarusso\\nStudio Colarusso\\n\\n> ${m.messaggio.replace(/\\n/g, \"\\n> \")}`);\n  $(\"#msgDetail\").innerHTML = `\n    <button class=\"btn ghost sm back\" id=\"backBtn\">← Tutti i messaggi</button>\n    <div class=\"d-head\">\n      <div><h3>${esc(m.nome)}</h3><a href=\"mailto:${esc(m.email)}\">${esc(m.email)}</a></div>\n      <time>${new Date(m.ts).toLocaleString(\"it-IT\", { dateStyle: \"long\", timeStyle: \"short\" })}</time>\n    </div>\n    <span class=\"tag\">${esc(m.motivo || \"Messaggio\")}</span>\n    ${o ? `<div class=\"d-opera\"><img src=\"${esc(imgSrc(o.anteprima || o.foto))}\" alt=\"\"><div><small>Opera richiesta</small>${esc(o.titolo)} · n. ${o.n}</div></div>` : m.opera ? `<span class=\"tag\">${esc(m.opera)}</span>` : \"\"}\n    <div class=\"d-msg\">${esc(m.messaggio)}</div>\n    <div class=\"seg\" id=\"seg\">${Object.entries(STATO).map(([k, v]) => `<button data-s=\"${k}\" class=\"${m.stato === k ? \"on\" : \"\"}\"><span class=\"dot ${k}\"></span>${v}</button>`).join(\"\")}</div>\n    <label class=\"f\"><span>Nota interna (la vedi solo tu)</span><textarea id=\"note\" rows=\"3\" placeholder=\"es. Risposto il 12/10, interessato a Décollage n. 15\">${esc(m.nota || \"\")}</textarea></label>\n    <div class=\"d-actions\">\n      <a class=\"btn\" href=\"mailto:${esc(m.email)}?subject=${subject}&body=${body}\">Rispondi via email</a>\n      <button class=\"btn ghost\" id=\"copyMail\">Copia email</button>\n      <span style=\"flex:1\"></span>\n      <button class=\"btn danger sm\" id=\"delMsg\">Elimina</button>\n    </div>`;\n  $(\"#inbox\").classList.add(\"reading\");\n  renderMessages();\n  // se è nuovo, passa a \"in corso\" appena lo apri\n  if (m.stato === \"nuovo\") setState(m, \"in-corso\", true);\n  $(\"#backBtn\").onclick = () => { $(\"#inbox\").classList.remove(\"reading\"); currentMsg = null; renderMessages(); };\n  $$(\"#seg button\").forEach(b => b.onclick = () => setState(m, b.dataset.s));\n  $(\"#note\").onblur = async e => {\n    if ((m.nota || \"\") === e.target.value) return;\n    try { await api(\"messages\", { id: m.id, action: \"nota\", nota: e.target.value }); m.nota = e.target.value; toast(\"Nota salvata.\", \"ok\"); } catch (err) { toast(err.message, \"bad\"); }\n  };\n  $(\"#copyMail\").onclick = () => { navigator.clipboard?.writeText(m.email); toast(\"Email copiata.\"); };\n  $(\"#delMsg\").onclick = async () => {\n    if (!confirm(`Eliminare definitivamente il messaggio di ${m.nome}?`)) return;\n    try { await api(\"messages\", { id: m.id, action: \"delete\" }); msgs = msgs.filter(x => x.id !== m.id); currentMsg = null;\n      $(\"#msgDetail\").innerHTML = '<div class=\"placeholder\">Messaggio eliminato.</div>'; $(\"#inbox\").classList.remove(\"reading\"); renderMessages(); toast(\"Messaggio eliminato.\", \"ok\");\n    } catch (err) { toast(err.message, \"bad\"); }\n  };\n}\nasync function setState(m, s, quiet) {\n  try {\n    await api(\"messages\", { id: m.id, action: \"stato\", stato: s }); m.stato = s;\n    $$(\"#seg button\").forEach(b => b.classList.toggle(\"on\", b.dataset.s === s));\n    renderMessages();\n    if (!quiet) toast(s === \"risolto\" ? \"Segnato come risolto.\" : \"Stato aggiornato.\", \"ok\");\n  } catch (err) { toast(err.message, \"bad\"); }\n}\n\n/* ---------------- Opere ---------------- */\nconst imgSrc = p => files.has(p) ? URL.createObjectURL(files.get(p)) : \"../\" + p;\nfunction renderWorks() {\n  const q = $(\"#workSearch\").value.trim().toLowerCase();\n  $(\"#grid\").innerHTML = sito.opere.map((o, i) => ({ o, i }))\n    .filter(({ o }) => workFilter === \"tutte\" || (workFilter === \"evidenza\" ? sito.selezione.includes(o.n) : o.nascosta))\n    .filter(({ o }) => !q || `${o.titolo} ${o.anno} ${o.n}`.toLowerCase().includes(q))\n    .map(({ o, i }) => `\n    <article class=\"card ${o.nascosta ? \"off\" : \"\"}\" data-i=\"${i}\">\n      <div class=\"badges\">\n        ${sito.selezione.includes(o.n) ? '<span class=\"badge\">★</span>' : \"\"}\n        ${sito.operaInApertura === o.n ? '<span class=\"badge red\">Apertura</span>' : \"\"}\n        ${o.nascosta ? '<span class=\"badge grey\">Nascosta</span>' : \"\"}\n        ${files.has(o.anteprima) ? '<span class=\"badge ok\">Da pubblicare</span>' : \"\"}\n      </div>\n      <div class=\"ph\"><img src=\"${esc(imgSrc(o.anteprima || o.foto))}\" alt=\"\" loading=\"lazy\"></div>\n      <div class=\"meta\"><b>${esc(o.titolo) || \"Senza titolo\"}</b><small>n. ${o.n}${o.anno ? \" · \" + esc(o.anno) : \"\"}${o.misure ? \" · \" + esc(o.misure) : \"\"}</small></div>\n    </article>`).join(\"\") || '<p class=\"empty\">Nessuna opera trovata.</p>';\n  renderHome();\n}\n$(\"#grid\").addEventListener(\"click\", e => { const c = e.target.closest(\".card\"); if (c) openEditor(+c.dataset.i); });\n$(\"#workSearch\").oninput = renderWorks;\n$$(\"#workFilter .chip\").forEach(c => c.onclick = () => { workFilter = c.dataset.f; $$(\"#workFilter .chip\").forEach(x => x.classList.toggle(\"on\", x === c)); renderWorks(); });\n$(\"#addBtn\").onclick = () => openEditor(-1);\n\n// Caricamento di più foto insieme: crea un'opera per ogni foto\n$(\"#multiFile\").onchange = async e => {\n  const list = [...e.target.files].filter(f => f.type.startsWith(\"image/\")); e.target.value = \"\";\n  if (!list.length) return;\n  const busy = $(\"#busy\"); busy.classList.remove(\"hidden\");\n  let k = 0;\n  for (const f of list) {\n    busy.textContent = `Preparo le foto… ${++k} / ${list.length}`;\n    try {\n      const p = await processImage(f, true, true);\n      const n = Math.max(0, ...sito.opere.map(x => x.n)) + 1;\n      const o = { n, titolo: `Décollage n. ${pad2(n)}`, anno: String(new Date().getFullYear()), tecnica: \"Décollage su carta\", misure: \"\", descrizione: \"\", genesi: \"\" };\n      addPhoto(o, p, true);\n      sito.opere.unshift(o);\n    } catch (err) { toast(`\"${f.name}\": ${err.message}`, \"bad\"); }\n  }\n  busy.classList.add(\"hidden\"); busy.textContent = \"Pubblicazione in corso…\";\n  renderWorks(); refresh();\n  toast(`${list.length} opere aggiunte in cima. Aprile per scrivere titolo e misure, poi pubblica.`, \"ok\");\n};\n\nfunction addPhoto(o, p, isNew) {\n  const stamp = Date.now().toString(36) + Math.random().toString(36).slice(2, 5);\n  const full = `img/opere/opera-${o.n}-${stamp}.${p.ext}`, thumb = `img/opere/opera-${o.n}-${stamp}-m.${p.ext}`;\n  if (!isNew) [o.foto, o.anteprima].forEach(x => { if (!x) return; if (files.has(x)) files.delete(x); else removed.add(x); });\n  files.set(full, p.full); files.set(thumb, p.thumb);\n  Object.assign(o, { foto: full, anteprima: thumb, w: p.w, h: p.h });\n}\n\n/* ---------------- Editor opera ---------------- */\nconst drawer = $(\"#drawer\"), bg = $(\"#drawerBg\");\nfunction parseMisure(s) { const m = String(s || \"\").match(/([\\d.,]+)\\s*(?:[×x]\\s*([\\d.,]+))?/); return m ? [m[1], m[2] || \"\"] : [\"\", \"\"]; }\nfunction openEditor(i) {\n  editing = i; pending = null; lastFile = null;\n  const o = i >= 0 ? sito.opere[i] : { titolo: \"\", anno: String(new Date().getFullYear()), tecnica: \"Décollage su carta\", misure: \"\", descrizione: \"\", genesi: \"\" };\n  $(\"#dTitle\").textContent = i >= 0 ? (o.titolo || \"Opera\") : \"Nuova opera\";\n  $(\"#fTitolo\").value = o.titolo || \"\"; $(\"#fAnno\").value = o.anno || \"\"; $(\"#fTecnica\").value = o.tecnica || \"\";\n  const [w, h] = parseMisure(o.misure); $(\"#fW\").value = w; $(\"#fH\").value = h;\n  $(\"#fDesc\").value = o.descrizione || \"\"; $(\"#fGenesi\").value = o.genesi || \"\";\n  $(\"#fSel\").checked = i >= 0 && sito.selezione.includes(o.n);\n  $(\"#fHero\").checked = i >= 0 && sito.operaInApertura === o.n;\n  $(\"#fHide\").checked = !!o.nascosta;\n  $(\"#dImg\").src = i >= 0 ? imgSrc(o.anteprima || o.foto) : \"\"; $(\"#dOrig\").removeAttribute(\"src\");\n  $(\"#dImg\").parentElement.classList.toggle(\"hidden\", i < 0);\n  $(\"#dOrig\").parentElement.classList.add(\"hidden\");\n  $(\"#dropTxt\").textContent = i >= 0 ? \"Sostituisci la foto\" : \"Carica la foto dell'opera\";\n  [\"#delBtn\", \"#upBtn\", \"#downBtn\"].forEach(s => $(s).classList.toggle(\"hidden\", i < 0));\n  $(\"#file\").value = \"\";\n  drawer.classList.remove(\"hidden\"); bg.classList.remove(\"hidden\"); drawer.scrollTop = 0;\n}\nfunction closeEditor() { drawer.classList.add(\"hidden\"); bg.classList.add(\"hidden\"); editing = null; pending = null; }\n$(\"#drawerClose\").onclick = closeEditor; bg.onclick = closeEditor;\ndocument.addEventListener(\"keydown\", e => { if (e.key === \"Escape\" && editing !== null) closeEditor(); });\n\nasync function handleFile(f) {\n  if (!f || !f.type.startsWith(\"image/\")) return toast(\"Scegli un file immagine.\", \"bad\");\n  lastFile = f;\n  try {\n    pending = await processImage(f, $(\"#optCut\").checked, $(\"#optTrim\").checked);\n    $(\"#dImg\").src = pending.preview; $(\"#dImg\").parentElement.classList.remove(\"hidden\");\n    $(\"#dOrig\").src = pending.orig; $(\"#dOrig\").parentElement.classList.remove(\"hidden\");\n  } catch (e) { toast(\"Non riesco a leggere questa immagine: \" + e.message, \"bad\"); }\n}\n$(\"#file\").onchange = e => handleFile(e.target.files[0]);\n[\"#optCut\", \"#optTrim\"].forEach(s => $(s).onchange = () => lastFile && handleFile(lastFile));\nconst drop = $(\"#drop\");\ndrop.addEventListener(\"dragover\", e => { e.preventDefault(); drop.classList.add(\"drag\"); });\ndrop.addEventListener(\"dragleave\", () => drop.classList.remove(\"drag\"));\ndrop.addEventListener(\"drop\", e => { e.preventDefault(); drop.classList.remove(\"drag\"); handleFile(e.dataTransfer.files[0]); });\n\n$(\"#saveBtn\").onclick = () => {\n  const isNew = editing < 0;\n  if (isNew && !pending) return toast(\"Carica prima la foto dell'opera.\", \"bad\");\n  const o = isNew ? { n: Math.max(0, ...sito.opere.map(x => x.n)) + 1 } : sito.opere[editing];\n  const w = $(\"#fW\").value.trim().replace(\".\", \",\"), h = $(\"#fH\").value.trim().replace(\".\", \",\");\n  Object.assign(o, {\n    titolo: $(\"#fTitolo\").value.trim() || `Décollage n. ${pad2(o.n)}`,\n    anno: $(\"#fAnno\").value.trim(), tecnica: $(\"#fTecnica\").value.trim(),\n    misure: w && h ? `${w} × ${h} cm` : w ? `Ø ${w} cm` : \"\",\n    descrizione: $(\"#fDesc\").value.trim(), genesi: $(\"#fGenesi\").value.trim()\n  });\n  if ($(\"#fHide\").checked) o.nascosta = true; else delete o.nascosta;\n  if (pending) addPhoto(o, pending, isNew);\n  if (isNew) sito.opere.unshift(o);\n  sito.selezione = sito.selezione.filter(n => n !== o.n);\n  if ($(\"#fSel\").checked) sito.selezione.push(o.n);\n  if ($(\"#fHero\").checked) sito.operaInApertura = o.n;\n  else if (sito.operaInApertura === o.n) sito.operaInApertura = (sito.opere.find(x => x.n !== o.n && !x.nascosta) || {}).n;\n  closeEditor(); renderWorks(); refresh();\n  toast(isNew ? \"Opera aggiunta. Ricordati di pubblicare.\" : \"Salvato. Ricordati di pubblicare.\", \"ok\");\n};\n$(\"#delBtn\").onclick = () => {\n  const o = sito.opere[editing];\n  if (!confirm(`Eliminare \"${o.titolo}\" dal sito?\\nSe vuoi solo toglierla per un po', usa \"Nascondi dal sito\".`)) return;\n  [o.foto, o.anteprima].forEach(p => { if (!p) return; if (files.has(p)) files.delete(p); else removed.add(p); });\n  sito.opere.splice(editing, 1);\n  sito.selezione = sito.selezione.filter(n => n !== o.n);\n  if (sito.operaInApertura === o.n) sito.operaInApertura = sito.opere[0] && sito.opere[0].n;\n  closeEditor(); renderWorks(); refresh();\n};\nfunction move(d) {\n  const j = editing + d; if (j < 0 || j >= sito.opere.length) return;\n  const a = sito.opere; [a[editing], a[j]] = [a[j], a[editing]]; editing = j; renderWorks(); refresh();\n  toast(d < 0 ? \"Spostata prima.\" : \"Spostata dopo.\");\n}\n$(\"#upBtn\").onclick = () => move(-1); $(\"#downBtn\").onclick = () => move(1);\n\n/* ---------------- Contatti e testi ---------------- */\nfunction getPath(path) { return path.split(\".\").reduce((o, k) => (o ? o[k] : undefined), sito); }\nfunction setPath(path, v) { const ks = path.split(\".\"); const last = ks.pop(); const o = ks.reduce((o, k) => (o[k] ||= {}), sito); o[last] = v; }\nfunction bindFields() {\n  $$(\"[data-bind]\").forEach(el => {\n    const v = getPath(el.dataset.bind), type = el.dataset.type;\n    el.value = type === \"paras\" ? (v || []).join(\"\\n\\n\") : type === \"tappe\" ? (v || []).map(t => t.join(\" | \")).join(\"\\n\") : (v || \"\");\n    el.oninput = () => {\n      const x = el.value;\n      setPath(el.dataset.bind,\n        type === \"paras\" ? x.split(/\\n\\s*\\n/).map(s => s.trim()).filter(Boolean)\n        : type === \"tappe\" ? x.split(\"\\n\").map(l => l.split(\"|\").map(s => s.trim())).filter(t => t[0]).map(t => [t[0], t.slice(1).join(\" | \")])\n        : x.trim());\n      refresh();\n    };\n  });\n}\n\n/* ---------------- Pubblicazione ---------------- */\nconst dirty = () => sito && (files.size || removed.size || JSON.stringify(sito) !== original);\nfunction refresh() {\n  const d = dirty();\n  $(\"#pub\").classList.toggle(\"show\", !!d);\n  if (d) $(\"#pubText\").textContent = `Hai modifiche non ancora pubblicate${files.size ? ` (${files.size / 2} foto nuove)` : \"\"}.`;\n}\nasync function publish() {\n  const busy = $(\"#busy\"); busy.classList.remove(\"hidden\");\n  try {\n    const uploaded = []; let k = 0;\n    for (const [path, blob] of files) {\n      busy.textContent = `Carico le foto… ${++k} / ${files.size}`;\n      const { sha } = await api(\"blob\", { content: await blobB64(blob), type: blob.type });\n      uploaded.push({ path, sha });\n    }\n    busy.textContent = \"Pubblicazione in corso…\";\n    await api(\"publish\", { sito, files: uploaded, removed: [...removed] });\n    original = JSON.stringify(sito); files.clear(); removed.clear();\n    renderWorks(); refresh();\n    toast(\"Pubblicato. Il sito si aggiorna da solo in circa un minuto.\", \"ok\");\n  } catch (e) { if (e.status !== 401) toast(\"Pubblicazione non riuscita: \" + e.message, \"bad\"); }\n  finally { busy.classList.add(\"hidden\"); busy.textContent = \"Pubblicazione in corso…\"; }\n}\n$(\"#publishBtn\").onclick = publish;\n$(\"#discardBtn\").onclick = async () => {\n  if (!confirm(\"Annullare tutte le modifiche non pubblicate?\")) return;\n  await loadData(); renderWorks(); bindFields(); refresh();\n};\naddEventListener(\"beforeunload\", e => { if (dirty()) { e.preventDefault(); e.returnValue = \"\"; } });\n\nlet tt;\nfunction toast(msg, kind = \"\") {\n  $$(\".toast\").forEach(t => t.remove());\n  const t = document.createElement(\"div\"); t.className = \"toast \" + kind; t.textContent = msg; document.body.append(t);\n  clearTimeout(tt); tt = setTimeout(() => t.remove(), 4200);\n}\n\n/* ---------------- Elaborazione foto: scontorno + ridimensionamento ---------------- */\nfunction loadImg(file) {\n  return new Promise((res, rej) => { const u = URL.createObjectURL(file); const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error(\"formato non supportato\")); i.src = u; });\n}\nfunction toCanvas(src, w, h, sx = 0, sy = 0, sw = src.width, sh = src.height) {\n  const c = document.createElement(\"canvas\"); c.width = w; c.height = h;\n  const x = c.getContext(\"2d\"); x.imageSmoothingQuality = \"high\"; x.drawImage(src, sx, sy, sw, sh, 0, 0, w, h); return c;\n}\n// Trova la parete chiara partendo dai bordi e restituisce il riquadro dell'opera\nfunction detect(img) {\n  const S = 600 / Math.max(img.width, img.height), W = Math.round(img.width * S), H = Math.round(img.height * S);\n  const d = toCanvas(img, W, H).getContext(\"2d\").getImageData(0, 0, W, H).data;\n  const L = new Float32Array(W * H), C = new Float32Array(W * H);\n  for (let i = 0; i < W * H; i++) {\n    const r = d[i * 4], g = d[i * 4 + 1], b = d[i * 4 + 2];\n    L[i] = 0.299 * r + 0.587 * g + 0.114 * b; C[i] = Math.max(r, g, b) - Math.min(r, g, b);\n  }\n  const B = Float32Array.from(L); // sfocatura 3x3\n  for (let y = 1; y < H - 1; y++) for (let x = 1; x < W - 1; x++) {\n    let s = 0; for (let j = -1; j <= 1; j++) for (let k = -1; k <= 1; k++) s += L[(y + j) * W + x + k]; B[y * W + x] = s / 9;\n  }\n  const bg = new Uint8Array(W * H), cand = i => {\n    const x = i % W, y = (i / W) | 0; if (x < 1 || y < 1 || x >= W - 1 || y >= H - 1) return L[i] > 115 && C[i] < 38;\n    const gx = B[i + 1] - B[i - 1], gy = B[i + W] - B[i - W];\n    return Math.abs(gx) + Math.abs(gy) < 7 && C[i] < 38 && L[i] > 115;\n  };\n  const q = [];\n  for (let x = 0; x < W; x++) { q.push(x, (H - 1) * W + x); } for (let y = 0; y < H; y++) { q.push(y * W, y * W + W - 1); }\n  let head = 0; const seen = new Uint8Array(W * H);\n  const seed = q.filter(i => cand(i)); seed.forEach(i => (seen[i] = 1, bg[i] = 1));\n  const Q = seed;\n  while (head < Q.length) {\n    const i = Q[head++], x = i % W, y = (i / W) | 0;\n    for (const n of [x > 0 ? i - 1 : -1, x < W - 1 ? i + 1 : -1, y > 0 ? i - W : -1, y < H - 1 ? i + W : -1]) {\n      if (n < 0 || seen[n]) continue; seen[n] = 1; if (cand(n)) { bg[n] = 1; Q.push(n); }\n    }\n  }\n  const rows = new Array(H).fill(0), cols = new Array(W).fill(0); let fgCount = 0;\n  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (!bg[y * W + x]) { rows[y]++; cols[x]++; fgCount++; }\n  const firstOver = (arr, lim) => arr.findIndex(v => v > lim), lastOver = (arr, lim) => arr.length - 1 - [...arr].reverse().findIndex(v => v > lim);\n  const y0 = firstOver(rows, W * 0.03), y1 = lastOver(rows, W * 0.03), x0 = firstOver(cols, H * 0.03), x1 = lastOver(cols, H * 0.03);\n  if (y0 < 0 || x0 < 0) return null;\n  const bw = x1 - x0 + 1, bh = y1 - y0 + 1, frac = (bw * bh) / (W * H);\n  if (frac > 0.95 || frac < 0.1) return null;\n  let inBox = 0; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) if (!bg[y * W + x]) inBox++;\n  return { x: x0 / S, y: y0 / S, w: bw / S, h: bh / S, round: inBox / (bw * bh) < 0.86 };\n}\n// Avvicina i bordi fino alla cornice scura, se c'è\nfunction trimToFrame(c) {\n  const W = c.width, H = c.height, d = c.getContext(\"2d\").getImageData(0, 0, W, H).data;\n  const lum = (x, y) => { const i = (y * W + x) * 4; return 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2]; };\n  const darkRow = y => { let n = 0, t = 0; for (let x = (W * 0.1) | 0; x < W * 0.9; x += 2) { t++; if (lum(x, y) < 70) n++; } return n / t > 0.55; };\n  const darkCol = x => { let n = 0, t = 0; for (let y = (H * 0.1) | 0; y < H * 0.9; y += 2) { t++; if (lum(x, y) < 70) n++; } return n / t > 0.55; };\n  const find = (test, n) => { for (let k = 0; k < n; k++) if (test(k)) return k; return null; };\n  const t = find(k => darkRow(k), H * 0.15), b = find(k => darkRow(H - 1 - k), H * 0.15);\n  const l = find(k => darkCol(k), W * 0.15), r = find(k => darkCol(W - 1 - k), W * 0.15);\n  if ([t, b, l, r].includes(null)) return c;\n  return toCanvas(c, W - l - r, H - t - b, l, t, W - l - r, H - t - b);\n}\nfunction blob(c, type, q) { return new Promise(r => c.toBlob(r, type, q)); }\nasync function processImage(file, cut, trim) {\n  const img = await loadImg(file);\n  let c = toCanvas(img, img.width, img.height);\n  let round = false;\n  if (cut) {\n    const box = detect(img);\n    if (box) {\n      round = box.round;\n      c = toCanvas(img, Math.round(box.w), Math.round(box.h), box.x, box.y, box.w, box.h);\n      if (round) {\n        const m = document.createElement(\"canvas\"); m.width = c.width; m.height = c.height;\n        const x = m.getContext(\"2d\"); x.beginPath(); x.ellipse(m.width / 2, m.height / 2, m.width / 2, m.height / 2, 0, 0, Math.PI * 2); x.clip(); x.drawImage(c, 0, 0); c = m;\n      } else if (trim) c = trimToFrame(c);\n    }\n  }\n  const fit = (src, max) => { const s = Math.min(1, max / Math.max(src.width, src.height)); return toCanvas(src, Math.round(src.width * s), Math.round(src.height * s)); };\n  const big = fit(c, 1800), small = fit(c, 900);\n  let type = \"image/webp\";\n  let full = await blob(big, type, 0.86);\n  if (!full || full.type !== \"image/webp\") { type = round ? \"image/png\" : \"image/jpeg\"; full = await blob(big, type, 0.86); }\n  const thumbB = await blob(small, type, 0.82);\n  const ext = type === \"image/webp\" ? \"webp\" : type === \"image/png\" ? \"png\" : \"jpg\";\n  return { full, thumb: thumbB, w: big.width, h: big.height, ext, preview: URL.createObjectURL(thumbB), orig: URL.createObjectURL(file) };\n}\n\n})();\n</script>\n</body>\n</html>\n";
